use std::collections::HashMap;

pub fn shortest(links: &HashMap<String, Vec<String>>, from: &str, to: &str) -> Option<Vec<String>> {
    let mut queue = vec![vec![from.to_string()]];
    while let Some(path) = queue.pop() {
        let at = path.last().expect("path is never empty");
        if at == to {
            return Some(path);
        }
        for next in links.get(at)? {
            let mut onward = path.clone();
            onward.push(next.clone());
            queue.push(onward);
        }
    }
    None
}

use std::collections::BTreeMap;

