use std::io::Write;

/// Every input the program consumed, in the order it consumed it. That plus the seed is the run.
pub fn run(args: &[String]) {
    let seed: u64 = args.iter().position(|a| a == "--seed").and_then(|i| args.get(i + 1)).and_then(|s| s.parse().ok()).unwrap_or(0);
    let mut out = std::io::stdout().lock();
    writeln!(out, "{{\"seed\":{seed},\"inputs\":[]}}").expect("stdout");
}

