/// Classic ddmin over the input list: halve, test, keep the half that still fails.
/// The predicate must be deterministic, which is the whole point of the rest of this repo.
pub fn ddmin<T: Clone>(inputs: Vec<T>, fails: impl Fn(&[T]) -> bool) -> Vec<T> {
    let mut current = inputs;
    let mut n = 2;
    while current.len() >= 2 {
        let chunk = current.len().div_ceil(n);
        let mut reduced = false;
        for i in 0..n {
            let start = i * chunk;
            if start >= current.len() { break; }
            let end = (start + chunk).min(current.len());
            let mut candidate = current[..start].to_vec();
            candidate.extend_from_slice(&current[end..]);
            if fails(&candidate) {
                current = candidate;
                n = (n - 1).max(2);
                reduced = true;
                break;
            }
        }
        if !reduced {
            if n >= current.len() { break; }
            n = (n * 2).min(current.len());
        }
    }
    current
}

