use replay_tools::shrink::ddmin;

#[test]
fn finds_the_one_bad_input() {
    let inputs: Vec<u32> = (0..64).collect();
    let out = ddmin(inputs, |xs| xs.contains(&37));
    assert_eq!(out, vec![37]);
}

