use std::process::Command;

fn main() {
    let dir = dirs_next::home_dir().expect("home").join("notes");
    std::fs::create_dir_all(&dir).expect("notes dir");
    let args: Vec<String> = std::env::args().skip(1).collect();
    match args.first().map(String::as_str) {
        Some("grep") => {
            let term = args.get(1).expect("a term");
            // read_dir order is whatever the filesystem feels like; a diff-able tool sorts.
            let mut paths: Vec<_> = std::fs::read_dir(&dir).expect("dir").map(|e| e.expect("entry").path()).collect();
            paths.sort();
            for path in paths {
                let text = std::fs::read_to_string(&path).unwrap_or_default();
                for line in text.lines().filter(|l| l.contains(term.as_str())) {
                    println!("{}: {line}", path.file_name().unwrap().to_string_lossy());
                }
            }
        }
        Some("yesterday") => open(&dir, chrono::Local::now() - chrono::Duration::days(1)),
        _ => open(&dir, chrono::Local::now()),
    }
}

fn open(dir: &std::path::Path, day: chrono::DateTime<chrono::Local>) {
    let file = dir.join(format!("{}.md", day.format("%Y-%m-%d")));
    let editor = std::env::var("EDITOR").unwrap_or_else(|_| "vi".into());
    Command::new(editor).arg(file).status().expect("editor");
}
